function n(v){ const x=Number(v); return Number.isFinite(x)?x:0; }
function data(v){ if(!v)return "—"; const d=new Date(String(v).slice(0,10)+"T12:00:00"); return Number.isNaN(d.getTime())?String(v):d.toLocaleDateString("pt-BR"); }
function paginar(lista,pagina,tamanho=25){const totalPaginas=Math.max(1,Math.ceil(lista.length/tamanho));const atual=Math.min(Math.max(1,pagina),totalPaginas);return {itens:lista.slice((atual-1)*tamanho,atual*tamanho),atual,totalPaginas};}
function Paginacao({total,pagina,setPagina,tamanho=25}){const paginas=Math.max(1,Math.ceil(total/tamanho));if(paginas<=1)return null;return <div className="flex items-center justify-between border-t border-slate-100 px-4 py-3 text-sm"><span className="text-slate-500">{total} registros · página {Math.min(pagina,paginas)} de {paginas}</span><div className="flex gap-2"><button className="btn-outline text-xs" disabled={pagina<=1} onClick={()=>setPagina(p=>Math.max(1,p-1))}>Anterior</button><button className="btn-outline text-xs" disabled={pagina>=paginas} onClick={()=>setPagina(p=>Math.min(paginas,p+1))}>Próxima</button></div></div>}
function somarMesesCalendario(data,meses){ const d=new Date(data),dia=d.getDate(); d.setDate(1); d.setMonth(d.getMonth()+meses); const ultimo=new Date(d.getFullYear(),d.getMonth()+1,0).getDate(); d.setDate(Math.min(dia,ultimo)); return d; }
function statusLote(l){
  const atual=n(l.totalAtual ?? l.total_atual);
  const minimo=n(l.qtdMinima ?? l.qtd_minima);
  if(atual<=0) return "ZERADO";
  if(minimo>0 && atual<=minimo) return "CRÍTICO";
  return "OK";
}
