 const abrirNovo=()=>{setForm({...vazio,dataChegada:new Date().toISOString().slice(0,10)});setEditando(null);setEtapa(1);setModal(true)},editar=l=>{setForm({...vazio,...l,produto:l.produto||"",referencia:l.referencia||l.especificacao||"",qtdKit:l.qtdKit||l.quantidadeKits||1,conteudoKit:l.conteudoKit||1,responsavel:l.responsavel||l.usuario||""});setEditando(l);setEtapa(1);setModal(true)};
 const escolherProduto=nome=>{const p=produtos.find(x=>x.produto===nome)||{};setForm(f=>({...f,produto:nome,grupo:p.grupo||f.grupo,unidade:p.unidade||f.unidade,qtdMinima:p.qtdMinima??f.qtdMinima,referencia:p.especificacao||f.referencia,conteudoKit:p.conteudoKit||f.conteudoKit}))};
 const normaliza=v=>String(v||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toUpperCase();
