 const produtosFiltrados=produtos.filter(x=>produtoAtivo(x)&&(!form.grupo||x.grupo===form.grupo)&&(normaliza(x.produto).includes(normaliza(form.produto))||normaliza(x.id).includes(normaliza(form.produto))||normaliza(x.especificacao).includes(normaliza(form.produto)))).slice(0,100);
