 const salvarEntrada=async()=>{if(!form.produto.trim()||!form.lote.trim()||total<=0)return setAviso({tipo:"erro",texto:"Informe produto, lote e quantidades válidas."});if(!editando&&form.itemPedidoId&&lotes.some(l=>l.itemPedidoId===form.itemPedidoId))return setAviso({tipo:"erro",texto:`O item do pedido ${form.pedidoCodigo||""} já possui uma entrada de estoque.`});if(!form.responsavel)return setAviso({tipo:"erro",texto:"Selecione o usuário responsável."});setSalvando(true);try{const codigo=editando?(editando.codigoID||editando.codigoAuto||editando.id):null,id=editando?.id,reg={...editando,...(id?{id}:{}),...(codigo?{codigoID:codigo,codigoAuto:codigo}:{}),...form,produto:form.produto.toUpperCase(),lote:form.lote.toUpperCase(),notaFiscal:form.notaFiscal.toUpperCase(),fornecedor:form.fornecedor.toUpperCase(),qtdTotal:total,qtdRetirada:editando?.qtdRetirada||0,totalAtual:editando?editando.totalAtual:total,qtdAtual:editando?editando.qtdAtual:total,statusValidade:editando?.statusValidade||"OK",statusCompra:editando?.statusCompra||"OK",origem:"GESTAO_ESTOQUE"};let salvo;if(editando){salvo=await estoqueLoteEditar(reg)}else{salvo=await estoqueEntrada({...reg,totalRecebido:total},{produto:reg.produto,lote:reg.lote,quantidade:total,unidade:reg.unidade,data:new Date().toISOString()})}const codigoSalvo=salvo?.lote?.codigoID||salvo?.lote?.codigoAuto||salvo?.lote?.id||codigo||"";const vinculoOk=!form.itemPedidoId||editando||salvo?.itemIntegrado;setModal(false);setAviso({tipo:vinculoOk?"ok":"erro",texto:`Entrada ${codigoSalvo} salva com sucesso.`+(form.itemPedidoId&&!editando?(vinculoOk?` Item do pedido ${form.pedidoCodigo||""} marcado como INTEGRADO.`:` Atenção: o servidor não confirmou a integração do item do pedido ${form.pedidoCodigo||""}. Confira a tabela de pedidos antes de gerar outra entrada.`):"")});await aoRecarregar()}catch(e){setAviso({tipo:"erro",texto:e.message})}finally{setSalvando(false)}};
