 const tiposFornecedor=useMemo(()=>[...new Set([...fornecedores.map(f=>String(f.tipoFornecedor||"").trim()),...regrasDocumentos.map(r=>String(r.tipoFornecedor||"").trim())].filter(Boolean))].sort((a,b)=>a.localeCompare(b,"pt-BR")),[fornecedores,regrasDocumentos]);
 const regrasDoFornecedor=x=>regrasDocumentos.filter(r=>String(r.tipoFornecedor||"").trim().toUpperCase()===String(x.tipoFornecedor||"").trim().toUpperCase()&&String(r.ativo||"SIM").toUpperCase()!=="NÃO");
 const fornecedoresBuscaForm=fornecedores.filter(f=>[f.id,f.nome,f.cnpj].join(" ").toLowerCase().includes(buscaForm.toLowerCase())).slice(0,20);
 /* resumoDoc vem ANTES de lista (auditoria de 28/09/2026): lista a chama durante o render, e com a
   declaração depois qualquer filtro de documentação diferente de TODOS derrubava a tela (TDZ). */ const resumoDoc=(x)=>{const regras=regrasDocumentos.filter(r=>String(r.tipoFornecedor||"").toUpperCase()===String(x.tipoFornecedor||"").toUpperCase()&&String(r.ativo||"SIM").toUpperCase()!=="NÃO");if(!regras.length)return "NÃO CONFIGURADO";const sts=regras.map(r=>{const tipo=tiposDocumentos.find(t=>t.id===r.tipoDocumentoId||t.idTipoDocumento===r.tipoDocumentoId)||{};const hist=documentos.filter(d=>d.fornecedorId===x.id&&(d.tipoDocumentoId===r.tipoDocumentoId||d.idTipoDocumento===r.tipoDocumentoId)&&String(d.ativo||"SIM").toUpperCase()!=="NÃO").sort((a,b)=>n(b.versao)-n(a.versao));return {regra:String(r.regra||"").toUpperCase(),status:statusDocFornecedor(r.regra,tipo,hist[0])}});if(sts.some(s=>s.regra==="OBRIGATÓRIO"&&s.status==="VENCIDO"))return "VENCIDO";if(sts.some(s=>s.regra==="OBRIGATÓRIO"&&s.status==="PENDENTE"))return "PENDENTE";if(sts.some(s=>s.regra==="OBRIGATÓRIO"&&s.status==="VENCENDO"))return "VENCENDO";return "REGULAR"}; const lista=fornecedores.filter(f=>[f.id,f.nome,f.cnpj,f.tipoServico,f.tipoFornecedor].join(" ").toLowerCase().includes(busca.toLowerCase())&&(filtroDoc==="TODOS"||resumoDoc(f)===filtroDoc)); const pagFornecedores=paginar(lista,pagina); 
 const gerarFape=async(x)=>{const avs=avaliacoes.filter(a=>a.fornecedorId===x.id).sort((a,b)=>String(a.dataAvaliacao).localeCompare(String(b.dataAvaliacao))),ini=avs.find(a=>String(a.tipoAvaliacao).toUpperCase()==="INICIAL"),reavs=avs.filter(a=>String(a.tipoAvaliacao).toUpperCase()==="REAVALIACAO_SEMESTRAL");if(!ini)return setAviso({tipo:"erro",texto:"Cadastre a avaliação inicial antes de gerar a FAPE."});setSalvando(true);try{const pdf=new jsPDF({unit:"mm",format:"a4"}),fmtData=v=>v?new Date(String(v).slice(0,10)+"T12:00:00").toLocaleDateString("pt-BR"):"—",nomes=["A empresa possui alvarás e licenças aplicáveis para funcionamento?","Quanto ao sistema de qualidade da empresa?","Possui certificação 17025:2017?","A empresa fornece certificado de materiais e/ou serviços?"];try{const blob=await fetch("https://minaslab.net/wp-content/themes/minaslab/img/logo.png").then(r=>{if(!r.ok)throw new Error("logo");return r.blob()}),url=URL.createObjectURL(blob),img=await new Promise((ok,err)=>{const el=new Image();el.onload=()=>ok(el);el.onerror=err;el.src=url}),cv=document.createElement("canvas");cv.width=img.naturalWidth||2048;cv.height=img.naturalHeight||612;const ctx=cv.getContext("2d");ctx.fillStyle="#FFFFFF";ctx.fillRect(0,0,cv.width,cv.height);ctx.drawImage(img,0,0);const logoJpeg=cv.toDataURL("image/jpeg",0.94);URL.revokeObjectURL(url);pdf.setFillColor(255,255,255);pdf.rect(14,5,51,17,"F");pdf.addImage(logoJpeg,"JPEG",15,7,48,14.35)}catch(_erroLogo){pdf.setFont("helvetica","bold");pdf.setFontSize(18);pdf.setTextColor(17,169,158);pdf.text("MinasLab",15,17)}pdf.setTextColor(30,41,59);pdf.setFontSize(9);pdf.setFont("helvetica","bold");pdf.text("FICHA DE AVALIAÇÃO DE PROVEDORES EXTERNOS",111,12,{align:"center"});pdf.setFont("helvetica","normal");pdf.setFontSize(6.5);pdf.text("FAPE · Gestão de Fornecedores",111,17,{align:"center"});pdf.setFontSize(7.5);pdf.setFont("helvetica","bold");pdf.text("FORNECEDOR:",160,11);pdf.setTextColor(17,169,158);pdf.text(String(x.id||"—"),184,11);pdf.setTextColor(30,41,59);pdf.setFont("helvetica","normal");pdf.text("Pag. 1",184,17);autoTable(pdf,{startY:23,theme:"grid",styles:{fontSize:7.5,cellPadding:2,lineColor:[148,163,184],lineWidth:.2},columnStyles:{0:{fontStyle:"bold",fillColor:[248,250,252]},2:{fontStyle:"bold",fillColor:[248,250,252]}},body:[["Fornecedor / Razão Social:",String(x.nome||"—").toUpperCase(),"CNPJ/Identificador:",x.cnpj||"—"],["Código / ID:",x.id||"—","Tipo de fornecedor:",x.tipoFornecedor||"—"],["Relação com a MinasLab:",x.relacaoMinaslab||x.relacao||"—","Periodicidade:",x.periodicidade||"—"],["Status:",x.status||"ATIVO","Próxima avaliação:",dataProxima(x)?fmtData(dataProxima(x)):"—"]]});let y=(pdf.lastAutoTable?.finalY||55)+6;pdf.setFont("helvetica","bold");pdf.setFontSize(9);pdf.setTextColor(30,41,59);pdf.text("AVALIAÇÃO INICIAL",15,y);autoTable(pdf,{startY:y+3,theme:"grid",styles:{fontSize:7.3,cellPadding:2,lineColor:[148,163,184],lineWidth:.2,valign:"middle"},headStyles:{fillColor:[241,245,249],textColor:[15,23,42],fontStyle:"bold"},head:[["Critério","Nota","Resposta / Evidência"]],body:nomes.map((nome,i)=>[nome,`${ini["criterio"+(i+1)+"Nota"]??"—"}/2`,ini["criterio"+(i+1)+"Relato"]||"—"])});y=(pdf.lastAutoTable?.finalY||100)+4;autoTable(pdf,{startY:y,theme:"grid",styles:{fontSize:7.5,cellPadding:2,lineColor:[148,163,184],lineWidth:.2},columnStyles:{0:{fontStyle:"bold",fillColor:[248,250,252]},2:{fontStyle:"bold",fillColor:[248,250,252]}},body:[["Data da avaliação:",fmtData(ini.dataAvaliacao),"Avaliador:",ini.avaliador||"—"],["Nota final:",`${ini.notaFinal??"—"} / 8`,"Classificação:",ini.classificacaoNota||"—"],["Resultado final:",ini.resultadoFinal||"—","Problema grave:",ini.problemaGrave||"NÃO"],["Observação:",ini.observacao||ini.relatoProblemaGrave||"—","",""]]});y=(pdf.lastAutoTable?.finalY||130)+7;if(reavs.length){pdf.setFont("helvetica","bold");pdf.setFontSize(9);pdf.text("REAVALIAÇÕES SEMESTRAIS",15,y);autoTable(pdf,{startY:y+3,theme:"grid",styles:{fontSize:7,cellPadding:2,lineColor:[148,163,184],lineWidth:.2},headStyles:{fillColor:[241,245,249],textColor:[15,23,42],fontStyle:"bold"},head:[["Data","Avaliador","Nota","Classificação","Resultado","Evidência"]],body:reavs.map(r=>[fmtData(r.dataAvaliacao),r.avaliador||"—",`${r.notaFinal??"—"}/8`,r.classificacaoNota||"—",r.resultadoFinal||"—",String(r.evidenciaReavaliacao||r.observacao||"—").slice(0,80)])});y=(pdf.lastAutoTable?.finalY||y)+8}else{pdf.setFont("helvetica","bold");pdf.setFontSize(9);pdf.text("REAVALIAÇÕES SEMESTRAIS",15,y);pdf.setFont("helvetica","normal");pdf.setFontSize(7.5);pdf.text("Nenhuma reavaliação semestral registrada.",15,y+5);y+=12}const dataUri=pdf.output("datauristring");const salvo=await estoqueFapeUpload({fornecedorId:x.id,arquivoBase64:dataUri});pdf.save(salvo?.nomeArquivo||`FAPE_${x.id}_${new Date().toISOString().slice(0,10)}.pdf`);await aoRecarregar();setAviso({tipo:"ok",texto:"FAPE gerada no padrão do Pedido de Compra e arquivada no histórico."})}catch(e){setAviso({tipo:"erro",texto:e.message})}finally{setSalvando(false)}};
 const abrirFape=async(f)=>{try{const url=await estoqueFapeUrl(f.id);if(!url)throw new Error("PDF da FAPE não localizado.");window.open(url,"_blank","noopener,noreferrer")}catch(e){setAviso({tipo:"erro",texto:e.message})}};
 const abrirDocumentos=(x)=>{setDocsDe(x);setDocForm({tipoDocumentoId:"",dataEmissao:"",dataValidade:"",referencia:"",observacao:"",arquivo:null})};
 const extrairIdPastaDrive=v=>{const s=String(v||"").trim(),m=s.match(/\/folders\/([a-zA-Z0-9_-]+)/)||s.match(/[?&]id=([a-zA-Z0-9_-]+)/);return m?m[1]:(/^[a-zA-Z0-9_-]+$/.test(s)?s:"")};
 const vincularPastaDrive=async x=>{const valor=window.prompt("Cole a URL ou o ID da pasta existente no Google Drive:");if(!valor)return;const id=extrairIdPastaDrive(valor);if(!id)return setAviso({tipo:"erro",texto:"URL ou ID da pasta inválido."});setSalvando(true);try{const r=await estoqueFornecedorDriveVincular(x.id,id);setGerenciar(r.registro||x);setAviso({tipo:"ok",texto:"Pasta validada no Google Drive e vinculada ao fornecedor."});await aoRecarregar()}catch(e){setAviso({tipo:"erro",texto:e.message})}finally{setSalvando(false)}};
 const criarPastaDrive=async x=>{setSalvando(true);try{const r=await estoqueFornecedorDriveCriar(x.id);setGerenciar(r.registro||x);setAviso({tipo:"ok",texto:"Pasta criada no Google Drive e vinculada ao fornecedor."});await aoRecarregar()}catch(e){setAviso({tipo:"erro",texto:e.message})}finally{setSalvando(false)}};
 const abrirPastaDrive=x=>{const url=x.pastaDriveUrl||x.PASTA_DRIVE_URL||(x.pastaDriveId||x.PASTA_DRIVE_ID?`https://drive.google.com/drive/folders/${x.pastaDriveId||x.PASTA_DRIVE_ID}`:"");if(!url)return setAviso({tipo:"erro",texto:"PASTA DO FORNECEDOR NÃO CONFIGURADA."});window.open(url,"_blank","noopener,noreferrer")};
 const enviarDocumento=async(fornecedorOverride=null)=>{const fornecedorDoc=fornecedorOverride||docsDe;if(!docForm?.tipoDocumentoId||!docForm?.arquivo)return setAviso({tipo:"erro",texto:"Selecione o tipo documental e o arquivo."});const tipo=tiposDocumentos.find(t=>(t.id||t.idTipoDocumento)===docForm.tipoDocumentoId)||{};if(String(tipo.possuiValidade||"NÃO").toUpperCase()==="SIM"&&!docForm.dataValidade)return setAviso({tipo:"erro",texto:"Informe a validade do documento."});setSalvando(true);try{const arquivo=docForm.arquivo;const base64=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(String(fr.result||""));fr.onerror=()=>reject(new Error("Não foi possível ler o arquivo."));fr.readAsDataURL(arquivo)});await estoqueDocumentoUpload({fornecedorId:fornecedorDoc.id,cnpj:fornecedorDoc.cnpj||"",tipoDocumentoId:docForm.tipoDocumentoId,dataEmissao:docForm.dataEmissao,dataValidade:docForm.dataValidade,referencia:docForm.referencia,observacao:docForm.observacao,nomeOriginal:arquivo.name,mimeType:arquivo.type,tamanhoArquivo:arquivo.size,arquivoBase64:base64});setDocForm({...docForm,arquivo:null,dataEmissao:"",dataValidade:"",referencia:"",observacao:""});await aoRecarregar();setAviso({tipo:"ok",texto:"Documento enviado; versões anteriores foram preservadas."})}catch(e){setAviso({tipo:"erro",texto:e.message})}finally{setSalvando(false)}};
 const visualizarDocumento=async(d)=>{try{const url=await estoqueDocumentoUrl(d.id);if(!url)throw new Error("Arquivo não localizado.");window.open(url,"_blank","noopener,noreferrer")}catch(e){setAviso({tipo:"erro",texto:e.message})}};
 const novo=()=>setForm({nome:"",cnpj:"",endereco:"",telefone:"",email:"",website:"",tipoServico:"COMPRAS",status:"ATIVO",relacaoMinaslab:"FORNECEDOR",tipoFornecedor:"COMPRAS",requerQualificacao:"SIM",periodicidade:"SEMESTRAL"});
