 const grupos=useMemo(()=>{const m=new Map();for(const p of pedidos){const k=codigoDe(p);if(!m.has(k))m.set(k,[]);m.get(k).push(p)}return [...m.entries()].sort((a,b)=>String(b[0]).localeCompare(String(a[0]),"pt-BR",{numeric:true}))},[pedidos]);
 const gruposFiltrados=grupos.filter(([codigo,itens])=>[codigo,...itens.flatMap(x=>[x.fornecedor,x.produto,x.especificacao])].join(" ").toLowerCase().includes(busca.toLowerCase())); const pagPedidos=paginar(gruposFiltrados,pagina); const proximoCodigo=()=>{let mx=0;for(const p of pedidos){const s=codigoDe(p);const m=String(s).match(/(\d+)/g);if(m)mx=Math.max(mx,Number(m[m.length-1])||0)}return "PC-"+String(mx+1).padStart(2,"0")};
 const rascunhoVazio=()=>({idx:null,produto:"",produtoId:"",especificacao:"",valor:"",grupo:"REAGENTE",unidade:"UN",conteudoKit:"",quantidadeKits:""});
 const cabecalhoVazio=()=>({dataPedido:"",fornecedor:"",cnpj:"",responsavel:"",observacao:"",prazoEntrega:"23 dias",formaPagamento:"Boleto",valorFrete:"0.00",valorImposto:"0.00"});
 const novo=()=>{setArquivoPedido(null);setArquivoChave(k=>k+1);setRascunho(rascunhoVazio());setForm({novo:true,pedidoCodigo:"",...cabecalhoVazio(),itens:[]})};
 const nomeChave=v=>String(v||"").trim().toUpperCase();
