 const salvarIR=async()=>{const item=inspecao.itens.find(x=>x.id===inspecao.itemId)||inspecao.itens[0];const notas=[inspecao.c1,inspecao.c2,inspecao.c3,inspecao.c4,inspecao.c5].map(Number);if(!inspecao.dataRecebimento||!inspecao.fabricante||!inspecao.lote||!inspecao.validade||!item)return setAviso({tipo:"erro",texto:"Data de recebimento, fabricante, lote e validade são obrigatórios."});if(notas.some(x=>!Number.isInteger(x)||x<0||x>3))return setAviso({tipo:"erro",texto:"As cinco notas da inspeção devem estar entre 0 e 3."});setSalvando(true);try{const r=await estoqueInspecaoRegistrar(item.id,{dataRecebimento:inspecao.dataRecebimento,fabricante:inspecao.fabricante,lote:inspecao.lote,validade:inspecao.validade,c1:notas[0],c2:notas[1],c3:notas[2],c4:notas[3],c5:notas[4],observacoes:inspecao.observacoes||""},inspecao.dataRecebimento);const reg=r.inspecao;let erroPdfIr="";try{erroPdfIr=await gerarPdfInspecao(reg)}catch(e){erroPdfIr=e.message||"erro desconhecido"}setInspecao(null);setAviso({tipo:erroPdfIr?"erro":"ok",texto:`Inspeção ${reg.idIr} registrada: ${reg.notaFinal}/15 — ${reg.parecer}.`+(erroPdfIr?` O laudo não foi salvo na pasta do Drive (${erroPdfIr}).`:" Laudo salvo na pasta do pedido.")});await aoRecarregar()}catch(e){setAviso({tipo:"erro",texto:e.message})}finally{setSalvando(false)}};
