// Logo MinasLab (arquivo do projeto) em JPEG para os PDFs; null se o navegador não conseguir carregar.
async function logoMinasLabJpeg(){try{const blob=await fetch(logoMinasLab).then(r=>{if(!r.ok)throw new Error("logo");return r.blob()}),url=URL.createObjectURL(blob),img=await new Promise((ok,err)=>{const el=new Image();el.onload=()=>ok(el);el.onerror=err;el.src=url}),cv=document.createElement("canvas");cv.width=img.naturalWidth||2048;cv.height=img.naturalHeight||612;const ctx=cv.getContext("2d");ctx.fillStyle="#FFFFFF";ctx.fillRect(0,0,cv.width,cv.height);ctx.drawImage(img,0,0);URL.revokeObjectURL(url);return cv.toDataURL("image/jpeg",0.94)}catch{return null}}
function baixarArquivo(conteudo,nome,tipo){const u=URL.createObjectURL(new Blob([conteudo],{type:tipo})),a=document.createElement("a");a.href=u;a.download=nome;a.click();URL.revokeObjectURL(u)}

