 const cel=(r,k)=>{const v=k==="codigoID"?(r.codigoID??r.codigoAuto??r.id):r[k];if(k==="validade"||k==="criadoEm")return v?data(v):"—";if(k==="falta"||k==="disponivel"||k==="minimo")return `${n(v).toLocaleString("pt-BR",{maximumFractionDigits:3})} ${r.unidade||""}`.trim();return v??"—"};
